# -*- coding: utf-8 -*-
# S5 (detail tables) and S6 (AI analysis)


def _tbl(module):
    return [d for d in _D.values() if d["module"] == module]


def _tbl_text(module):
    return "؛ ".join("(%d) «%s»" % (i, d["title"]) for i, d in enumerate(_tbl(module), 1))


def _cols_text(key):
    return "، ".join("«%s»" % c["title"] for c in _D[key]["columns"])


def _note_text(key):
    return " ".join(_D[key]["notes"])


_MODTITLE = {"finance": "مالی و خزانه", "sales": "فروش", "projects": "پروژه‌ها", "production": "تولید و نگهداری", "quality": "کیفیت", "inventory": "انبار",
             "procurement": "تأمین و خرید", "service": "خدمات پس از فروش", "office": "اداری", "ai": "هوش مصنوعی"}
_ALL_TABLES = ("ستون‌ها، توضیح زیر عنوان و پارامترهای هر جدول را در پیوست «جدول‌های جزئیات» راهنما ببینید. جدولی که ردیف ندارد (پایگاه تازه) پیام «ردیفی برای نمایش نیست؛ هیچ رکوردی در این جدول با شرایط امروز جور نیست.» را می‌دهد و خطا نیست.")


def _module(mod, key, title, checks, expect, extra_steps=()):
    n = len(_tbl(mod))
    steps = ["%s: در ستون کناری «همه‌ی جدول‌های جزئیات» را بزنید و در گروه «%s» (%d جدول) یکی‌یکی همه‌ی جدول‌ها را باز کنید: %s. هر جدول را با Esc ببندید." % (DASH, _MODTITLE[mod], n, _tbl_text(mod)),
             "برای هر جدول: عنوان، سطر زیر عنوان («N ردیف»، «وضعیت تا …» و «مبالغ به ریال» اگر ستون ریالی دارد)، توضیح زیر آن (اگر هست) و عنوان ستون‌ها را بخوانید.",
             "اگر ردیف دارد: ستون‌های ریالی را ببینید (عدد کامل با جداکننده‌ی هزارگان؛ اشاره‌گر روی عدد، مقدار کوتاه و کامل را می‌دهد)، ستون‌های تاریخ شمسی و ستون‌های وضعیت را بخوانید."]
    steps += list(checks) + list(extra_steps)
    t(key, "S5", title, CEO, steps, expect + " " + _ALL_TABLES)


